const LANGUAGES = ['en', 'fr', 'de'];
function clampInt(v, lo, hi, def) {
  const n = Number(v);
  if (!Number.isFinite(n)) return def;
  return Math.max(lo, Math.min(hi, Math.round(n)));
}

const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;
const filters = body.filters && typeof body.filters === 'object' ? body.filters : {};

const niche = String(body.niche || '').trim();
const language = LANGUAGES.includes(body.language) ? body.language : 'en';
const location = String(body.location || 'United States').trim();
const seed = Array.isArray(body.seed_keywords)
  ? body.seed_keywords.map(k => String(k).trim().toLowerCase()).filter(Boolean).slice(0, 60)
  : [];
const monetization = Array.isArray(filters.monetization) ? filters.monetization.map(String) : [];
const ad_networks = Array.isArray(filters.ad_networks) ? filters.ad_networks.map(String) : [];

if (!niche && !seed.length) throw new Error('niche or seed_keywords is required');

const inputs = {
  niche, language, location,
  filters: {
    da_max: clampInt(filters.da_max, 0, 100, 25),
    traffic_min: Math.max(0, Number(filters.traffic_min) || 1000),
    monetization,
    ad_networks
  },
  seed_keywords: seed,
  max_keywords: clampInt(body.max_keywords, 5, 60, 30),
  serp_depth: clampInt(body.serp_depth, 10, 30, 20),
  max_domains: clampInt(body.max_domains, 5, 80, 40),
  started_at: Date.now(),
  requested_at: body.requested_at || new Date().toISOString()
};

return [{ json: { inputs, has_seeds: seed.length > 0 } }];

const inputs = $json.inputs;
const seeds = inputs.seed_keywords.slice(0, inputs.max_keywords);
return seeds.map(kw => ({ json: { inputs, keyword: kw, search_volume: null, source: 'user' } }));

const inputs = $('Normalize Input').first().json.inputs;
const resp = $input.first().json;
const items = (resp && resp.tasks && resp.tasks[0] && resp.tasks[0].result && resp.tasks[0].result[0] && resp.tasks[0].result[0].items) || [];

const kws = items
  .map(i => ({
    keyword: String(i.keyword || '').trim().toLowerCase(),
    search_volume: i.keyword_info && i.keyword_info.search_volume,
    cpc: i.keyword_info && i.keyword_info.cpc,
    kd: i.keyword_properties && i.keyword_properties.keyword_difficulty
  }))
  .filter(k => k.keyword)
  .slice(0, inputs.max_keywords);

// Fallback: if expansion returned nothing usable, run with just the raw niche term.
const use = kws.length ? kws : [{ keyword: inputs.niche, search_volume: null }];

return use.map(k => ({ json: { inputs, keyword: k.keyword, search_volume: k.search_volume, source: 'expanded' } }));

const upstreamItems = $('Merge Keyword Sources').all();
const myIdx = $itemIndex;
const upstream = upstreamItems[myIdx] ? upstreamItems[myIdx].json : { keyword: '', search_volume: null };
const keyword = upstream.keyword || '';
const search_volume = upstream.search_volume || null;

const resp = $input.item.json || {};
const items = (resp && resp.tasks && resp.tasks[0] && resp.tasks[0].result && resp.tasks[0].result[0] && resp.tasks[0].result[0].items) || [];

const domains = items
  .filter(i => i.type === 'organic')
  .map(i => ({
    keyword,
    search_volume,
    domain: String(i.domain || '').replace(/^www\./, '').toLowerCase(),
    position: i.rank_absolute,
    url: i.url
  }))
  .filter(d => d.domain);

return { json: { keyword, domains, count: domains.length } };

const BLOCK = new Set([
  'youtube.com','facebook.com','instagram.com','twitter.com','x.com',
  'tiktok.com','pinterest.com','reddit.com','quora.com','medium.com',
  'linkedin.com','wikipedia.org','amazon.com','amazon.co.uk','amazon.ca',
  'amazon.in','amazon.de','amazon.fr',
  'ebay.com','etsy.com','walmart.com','target.com','homedepot.com',
  'lowes.com','wayfair.com','ikea.com','apple.com','microsoft.com',
  'google.com','yahoo.com','bing.com','forbes.com','nytimes.com',
  'washingtonpost.com','cnn.com','bbc.com','theguardian.com','huffpost.com',
  'businessinsider.com','buzzfeed.com','vox.com','thespruce.com',
  'thespruceeats.com','hgtv.com','bobvila.com','familyhandyman.com',
  'goodhousekeeping.com','housebeautiful.com','architecturaldigest.com',
  'elledecor.com','realsimple.com','bhg.com','countryliving.com',
  'marthastewart.com','thisoldhouse.com'
]);

const inputs = $('Normalize Input').first().json.inputs;
const all = $input.all();
const rawDomainCount = all.reduce((s, it) => s + ((it.json && it.json.count) || 0), 0);

const map = new Map();
for (const it of all) {
  const arr = (it.json && it.json.domains) || [];
  for (const d of arr) {
    if (BLOCK.has(d.domain)) continue;
    if (!map.has(d.domain)) map.set(d.domain, { domain: d.domain, niche_keywords: [] });
    map.get(d.domain).niche_keywords.push({
      keyword: d.keyword, position: d.position, url: d.url, search_volume: d.search_volume
    });
  }
}

const out = [...map.values()];
return out.map(d => ({ json: { inputs, domain: d.domain, niche_keywords: d.niche_keywords, raw_domain_count: rawDomainCount, unique_domain_count: out.length } }));

const inputs = $('Normalize Input').first().json.inputs;
const upstream = $('Aggregate & Dedupe Domains').all();
const enrich = $input.all();

// Zip upstream domain context with Domain Rank Overview response (traffic + keyword count).
// Note: domain_rank_overview's traffic/count live at result.items[0].metrics.organic
// (NOT result.metrics — that's an empty branch). The endpoint does NOT return a
// domain rank score — we fetch that separately from backlinks/bulk_ranks below.
const rows = upstream.map((u, i) => {
  const ctx = u.json || {};
  const resp = (enrich[i] && enrich[i].json) || {};
  const result = resp && resp.tasks && resp.tasks[0] && resp.tasks[0].result && resp.tasks[0].result[0];
  const item = result && result.items && result.items[0];
  const metrics = (item && item.metrics) || {};
  const organic = metrics.organic || {};
  return {
    domain: ctx.domain,
    niche_keywords: ctx.niche_keywords || [],
    da: null,
    global_traffic: Math.round(Number(organic.etv || 0)),
    ranking_keywords_total: Number(organic.count || 0)
  };
});

// Bulk-fetch Domain Rank for every domain in one backlinks API call.
// DataForSEO returns rank 0-1000 — normalize to 0-100 for DA-equivalence.
const targets = rows.map(r => r.domain).filter(Boolean);
let drError = null;
if (targets.length) {
  try {
    const drResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.dataforseo.com/v3/backlinks/bulk_ranks/live',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Basic YWJoaXNoZWtib2xhcnNoZXR0eUBnbWFpbC5jb206NmFhNjljYTBhNGJmODE4OA=='
      },
      body: [{ targets }],
      json: true,
      timeout: 60000
    });
    const drItems = (drResp && drResp.tasks && drResp.tasks[0] && drResp.tasks[0].result && drResp.tasks[0].result[0] && drResp.tasks[0].result[0].items) || [];
    const drMap = new Map(drItems.map(i => [String(i.target || '').replace(/^www\./, '').toLowerCase(), i.rank]));
    for (const r of rows) {
      const rk = drMap.get(r.domain);
      r.da = typeof rk === 'number' ? Math.round(rk / 10) : null;
    }
  } catch (e) { drError = String((e && e.message) || e); }
}

function scorePerf(traffic, da) {
  if (!traffic || traffic < 1) return 0;
  const safeDa = typeof da === 'number' ? da : 50;
  return Math.round(traffic / (safeDa + 1));
}

const pre = rows
  .filter(r => (r.da == null || r.da <= inputs.filters.da_max))
  .filter(r => r.global_traffic >= inputs.filters.traffic_min)
  .sort((a, b) => scorePerf(b.global_traffic, b.da) - scorePerf(a.global_traffic, a.da))
  .slice(0, inputs.max_domains);

if (!pre.length) {
  return [{ json: { inputs, _empty: true, pre_filtered_count: 0, raw_rows: rows.length, dr_error: drError } }];
}

return pre.map(r => ({
  json: {
    inputs,
    domain: r.domain,
    niche_keywords: r.niche_keywords,
    da: r.da,
    global_traffic: r.global_traffic,
    ranking_keywords_total: r.ranking_keywords_total,
    pre_filtered_count: pre.length,
    raw_rows: rows.length
  }
}));

const ctx = $('Pre-Filter Domains').all()[$itemIndex];
const meta = (ctx && ctx.json) || {};

// Sentinel pass-through: pre-filter found nothing, just propagate empty.
if (meta._empty) return { json: meta };

const resp = $input.item.json || {};
const data = (resp && resp.data) || {};
const html = String(data.html || '');
const md = String(data.markdown || '');
const content = html || md;

const RULES = [
  ['adsense',    /pagead2\.googlesyndication\.com|data-ad-client=["']ca-pub-|adsbygoogle\.js/i],
  ['mediavine',  /scripts\.mediavine\.com|mediavine-/i],
  ['ezoic',      /ezoic\.(com|net)|ezoic\.js|ezojs\.com|ezoic-id/i],
  ['amazon',     /amzn\.to|amazon\.[a-z.]{2,6}\/[^"'<>\s]*[?&]tag=|associates-amazon|as\.li\//i],
  ['affiliate',  /as an amazon associate|affiliate (link|disclosure)|affiliate-disclos|"affiliate"|impact\.com|clickbank|cj\.com|shareasale|awin\.com|partnerstack|rakutenadvertising/i],
  ['shop',       /woocommerce|shopify|\/shop\/|\/store\/|add to cart|\.add-to-cart|product-add-to-cart/i],
  ['wordpress',  /wp-content|wp-includes|wp-json|generator["'\s]+content=["']WordPress/i],
  ['shopify',    /cdn\.shopify\.com|shopify\.com\/s\//i]
];
const signals = [];
for (const [tag, re] of RULES) if (re.test(content)) signals.push(tag);

const hasFcError = resp && (resp.success === false || resp.error);
const scrape_source = hasFcError ? 'fallback' : 'firecrawl';
const scrape_error = hasFcError ? (resp.error || resp.message || 'firecrawl error') : null;

return { json: {
  inputs: meta.inputs,
  domain: meta.domain,
  niche_keywords: meta.niche_keywords,
  da: meta.da,
  global_traffic: meta.global_traffic,
  ranking_keywords_total: meta.ranking_keywords_total,
  pre_filtered_count: meta.pre_filtered_count,
  raw_rows: meta.raw_rows,
  signals,
  scrape_source,
  scrape_error
} };

const inputs = $('Normalize Input').first().json.inputs;
const keywordItems = $('Merge Keyword Sources').all().map(it => ({
  keyword: (it.json && it.json.keyword) || '',
  search_volume: it.json && it.json.search_volume,
  source: (it.json && it.json.source) || 'expanded'
}));

const rows = $input.all().map(it => it.json).filter(r => !r._empty);
const rawRows = rows.length ? rows[0].raw_rows : 0;
const preFilteredCount = rows.length ? rows[0].pre_filtered_count : 0;

// Debug snapshot — surface what the SERP HTTP node actually returned, so we can
// tell whether the empty pipeline is an auth issue, response-shape mismatch,
// or blocklist eating everything. Remove once stable.
let _debug = null;
if (rawRows === 0) {
  let serpAll = [];
  try { serpAll = $('DataForSEO SERP').all(); } catch (e) {}
  const first = serpAll[0] && serpAll[0].json;
  const result0 = first && first.tasks && first.tasks[0] && first.tasks[0].result && first.tasks[0].result[0];
  const items0 = (result0 && result0.items) || [];
  let extracted = [];
  try { extracted = $('Extract Domains').all(); } catch (e) {}
  const extractTotalDomains = extracted.reduce((s, it) => s + (((it.json && it.json.count) || 0)), 0);
  let agg = [];
  try { agg = $('Aggregate & Dedupe Domains').all(); } catch (e) {}
  let drank = [];
  try { drank = $('Domain Rank Overview').all(); } catch (e) {}
  let prefilt = [];
  try { prefilt = $('Pre-Filter Domains').all(); } catch (e) {}
  _debug = {
    serp_response_count: serpAll.length,
    first_serp_status_code: first && first.status_code,
    first_serp_items_count: items0.length,
    first_serp_organic_sample: items0.filter(i => i.type === 'organic').slice(0, 3).map(i => ({ domain: i.domain, rank: i.rank_absolute, url: i.url })),
    extract_domains_count: extracted.length,
    extract_first_count: extracted[0] && extracted[0].json && extracted[0].json.count,
    extract_total_domains_across_all: extractTotalDomains,
    aggregate_output_count: agg.length,
    aggregate_first_keys: agg[0] && agg[0].json ? Object.keys(agg[0].json) : null,
    aggregate_first_domain: agg[0] && agg[0].json && agg[0].json.domain,
    aggregate_first_raw_domain_count: agg[0] && agg[0].json && agg[0].json.raw_domain_count,
    aggregate_first_unique_domain_count: agg[0] && agg[0].json && agg[0].json.unique_domain_count,
    aggregate_sample_domains: agg.slice(0, 8).map(it => it.json && it.json.domain),
    domain_rank_output_count: drank.length,
    domain_rank_first_status: drank[0] && drank[0].json && drank[0].json.status_code,
    domain_rank_first_keys: drank[0] && drank[0].json ? Object.keys(drank[0].json).slice(0, 10) : null,
    prefilter_output_count: prefilt.length,
    prefilter_first_keys: prefilt[0] && prefilt[0].json ? Object.keys(prefilt[0].json) : null,
    prefilter_first_empty: prefilt[0] && prefilt[0].json && prefilt[0].json._empty,
    prefilter_first_da: prefilt[0] && prefilt[0].json && prefilt[0].json.da,
    prefilter_first_traffic: prefilt[0] && prefilt[0].json && prefilt[0].json.global_traffic
  };
}

function scorePerf(traffic, da) {
  if (!traffic || traffic < 1) return 0;
  const safeDa = typeof da === 'number' ? da : 50;
  return Math.round(traffic / (safeDa + 1));
}

const monSel = inputs.filters.monetization || [];
const adSel = inputs.filters.ad_networks || [];
function passesMonetization(sigs) {
  if (!monSel.length) return true;
  const hasAds = sigs.includes('adsense') || sigs.includes('mediavine') || sigs.includes('ezoic');
  const hasEcom = sigs.includes('shop') || sigs.includes('shopify');
  const hasAff = sigs.includes('amazon') || sigs.includes('affiliate');
  for (const m of monSel) {
    if (m === 'monetized_with_ads' && hasAds) return true;
    if (m === 'not_monetized_with_ads' && !hasAds) return true;
    if (m === 'ecommerce' && hasEcom) return true;
    if (m === 'not_ecommerce' && !hasEcom) return true;
    if (m === 'affiliate' && hasAff) return true;
    if (m === 'no_monetization' && !hasAds && !hasEcom && !hasAff) return true;
  }
  return false;
}
function passesAdNetwork(sigs) {
  if (!adSel.length) return true;
  const present = sigs.filter(s => s === 'adsense' || s === 'mediavine' || s === 'ezoic');
  return adSel.some(a => present.includes(a));
}

const final = rows
  .filter(r => passesMonetization(r.signals || []))
  .filter(r => passesAdNetwork(r.signals || []))
  .map(r => ({
    domain: r.domain,
    url: 'https://' + r.domain,
    signals: r.signals || [],
    main_topic: inputs.niche,
    niche: inputs.niche,
    perf: scorePerf(r.global_traffic, r.da),
    da: r.da,
    global_traffic: r.global_traffic,
    us_traffic: null,
    pages_count: null,
    ranking_keywords_total: r.ranking_keywords_total,
    ranking_keywords_in_niche: (r.niche_keywords || []).length,
    top_niche_keywords: (r.niche_keywords || [])
      .slice()
      .sort((a, b) => (a.position || 999) - (b.position || 999))
      .slice(0, 8),
    scrape_source: r.scrape_source,
    scrape_error: r.scrape_error
  }))
  .sort((a, b) => b.perf - a.perf);

return [{ json: {
  request: inputs,
  total_weak_websites: final.length,
  domains: final,
  diagnostics: {
    keywords_used: keywordItems.length,
    raw_domains_seen: rawRows,
    after_pre_filter: preFilteredCount,
    after_signal_filter: final.length,
    elapsed_ms: Date.now() - inputs.started_at,
    _debug
  },
  keywords: keywordItems,
  generated_at: new Date().toISOString()
} }];
